namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public string Description { get; set; } = "";
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();
    private int _nextId;

    public static readonly string[] Categories =
        ["Breakfast", "Lunch", "Dinner", "Desserts", "Appetizers", "Beverages"];

    public RecipeService()
    {
        _recipes = CreateSeedData();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && stars is >= 1 and <= 5)
            {
                recipe.TotalRatingPoints += stars;
                recipe.RatingCount++;
            }
        }
    }

    public Recipe AddRecipe(string title, string category, List<string> ingredients, List<string> steps)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = title,
                Category = category,
                Ingredients = ingredients,
                Steps = steps
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }

    private static List<Recipe> CreateSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a weekend morning.",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
            Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Pour batter onto a hot greased griddle.", "Flip when bubbles form on the surface.", "Serve with maple syrup and fresh berries."],
            TotalRatingPoints = 18, RatingCount = 4
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, healthy, and endlessly customizable.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes", "2 eggs (optional)"],
            Steps = ["Toast the bread until golden.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread the avocado mixture on toast.", "Top with red pepper flakes and a fried egg if desired."],
            TotalRatingPoints = 14, RatingCount = 3
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A crisp, tangy classic with homemade dressing.",
            Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "2 tbsp Caesar dressing", "1 grilled chicken breast (optional)"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss with Caesar dressing.", "Top with croutons and shaved parmesan.", "Add sliced grilled chicken if desired."],
            TotalRatingPoints = 12, RatingCount = 3
        },
        new()
        {
            Id = 4, Title = "Chicken Wrap", Category = "Lunch",
            Description = "A quick protein-packed wrap for busy days.",
            Ingredients = ["2 flour tortillas", "1 grilled chicken breast", "½ cup lettuce", "¼ cup tomatoes", "2 tbsp ranch dressing"],
            Steps = ["Slice the grilled chicken.", "Lay out tortillas and spread ranch dressing.", "Add chicken, lettuce, and tomatoes.", "Roll up tightly and slice in half."],
            TotalRatingPoints = 8, RatingCount = 2
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A hearty Italian classic with rich meat sauce.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic", "800g crushed tomatoes", "2 tbsp tomato paste", "1 tsp oregano", "Salt and pepper", "Parmesan cheese"],
            Steps = ["Cook spaghetti according to package directions.", "Brown the ground beef in a large pan.", "Add onion and garlic, cook until soft.", "Stir in crushed tomatoes, tomato paste, and oregano.", "Simmer for 20 minutes.", "Serve sauce over spaghetti with parmesan."],
            TotalRatingPoints = 20, RatingCount = 4
        },
        new()
        {
            Id = 6, Title = "Grilled Salmon", Category = "Dinner",
            Description = "Perfectly seasoned salmon with a smoky char.",
            Ingredients = ["4 salmon fillets", "2 tbsp olive oil", "1 lemon", "2 cloves garlic, minced", "1 tsp paprika", "Salt and pepper", "Fresh dill"],
            Steps = ["Mix olive oil, lemon juice, garlic, paprika, salt, and pepper.", "Marinate salmon for 15 minutes.", "Preheat grill to medium-high.", "Grill salmon 4–5 minutes per side.", "Garnish with fresh dill and lemon wedges."],
            TotalRatingPoints = 15, RatingCount = 3
        },
        new()
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "A decadent dessert with a molten chocolate center.",
            Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour", "Butter and cocoa for ramekins"],
            Steps = ["Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into buttered ramekins dusted with cocoa.", "Bake 12–14 minutes until edges are firm but center is soft.", "Invert onto plates and serve immediately."],
            TotalRatingPoints = 25, RatingCount = 5
        },
        new()
        {
            Id = 8, Title = "Bruschetta", Category = "Appetizers",
            Description = "Fresh tomato and basil on crispy toasted bread.",
            Ingredients = ["1 baguette", "4 ripe tomatoes", "2 cloves garlic", "Fresh basil", "2 tbsp olive oil", "1 tbsp balsamic vinegar", "Salt and pepper"],
            Steps = ["Dice tomatoes and mix with chopped basil, olive oil, vinegar, salt, and pepper.", "Slice baguette and toast until golden.", "Rub each slice with a cut garlic clove.", "Top with the tomato mixture and serve."],
            TotalRatingPoints = 16, RatingCount = 4
        },
        new()
        {
            Id = 9, Title = "Iced Matcha Latte", Category = "Beverages",
            Description = "A refreshing green tea drink with creamy milk.",
            Ingredients = ["2 tsp matcha powder", "2 tbsp hot water", "1 cup milk", "1 tbsp honey or sweetener", "Ice"],
            Steps = ["Sift matcha powder into a bowl.", "Add hot water and whisk until smooth.", "Fill a glass with ice.", "Pour milk over ice.", "Add the matcha mixture and sweetener.", "Stir well and enjoy."],
            TotalRatingPoints = 10, RatingCount = 2
        },
    ];
}

