}

@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 d-flex align-items-center gap-2">
    <span class="fw-bold">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                style="color: @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "#ffc107" : "#dee2e6"); cursor: pointer; border: none;"
                @onmouseover="() => hoveredStar = star"
                @onmouseout="() => hoveredStar = 0"
                @onclick="() => SubmitRating(star)"
                title="@star star(s)">
            ★
        </button>
    }

    @if (submitted)
    {
        <span class="badge bg-success ms-2">Thanks for rating!</span>
    }

    <span class="text-muted ms-2">
        @if (recipe is not null && recipe.RatingCount > 0)
        {
            @($"{recipe.AverageRating:F1} avg ({recipe.RatingCount} ratings)")
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int hoveredStar;
    private int selectedStar;
    private bool submitted;
    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label class="form-label fw-bold">Title</label>
        <InputText @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Category</label>
        <InputSelect @bind-Value="model.Category" class="form-select">
            <option value="">— Select a category —</option>
            @foreach (var cat in RecipeService.Categories)
            {
                <option value="@cat">@cat</option>
            }
        </InputSelect>
        <ValidationMessage For="() => model.Category" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Ingredients</label>
        <p class="text-muted small">One ingredient per line</p>
        <InputTextArea @bind-Value="model.IngredientsText" class="form-control" rows="5"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => model.IngredientsText" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Steps</label>
        <p class="text-muted small">One step per line</p>
        <InputTextArea @bind-Value="model.StepsText" class="form-control" rows="5"
                       placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        <ValidationMessage For="() => model.StepsText" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
    <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? errorMessage;

    private void HandleSubmit()
    {
        var ingredients = model.IngredientsText?
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList() ?? [];

        var steps = model.StepsText?
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList() ?? [];

        if (string.IsNullOrWhiteSpace(model.Title) || string.IsNullOrWhiteSpace(model.Category))
        {
            errorMessage = "Please fill in the title and category.";
            return;
        }

        if (ingredients.Count == 0 || steps.Count == 0)
        {
            errorMessage = "Please provide at least one ingredient and one step.";
            return;
        }

        var recipe = RecipeService.AddRecipe(model.Title!, model.Category!, ingredients, steps);
        Navigation.NavigateTo($"recipe/{recipe.Id}");
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string? Title { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string? Category { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string? IngredientsText { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string? StepsText { get; set; }
    }
}

